import cv2from ultralytics import YOLOfrom src.tracking import trackingmodel = YOLO("model/yolo26s.pt")cap  = cv2.VideoCapture('data/ScreenRecorderProject49.mp4')DEFAULT_WIDTH = 1280DEFAULT_HEIGHT = 720cap.set(cv2.CAP_PROP_FRAME_WIDTH, DEFAULT_WIDTH)cap.set(cv2.CAP_PROP_FRAME_HEIGHT, DEFAULT_HEIGHT)fps = cap.get(cv2.CAP_PROP_FPS)width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))writer = cv2.VideoWriter("final/output.mp4",                          cv2.VideoWriter_fourcc(*'mp4v'),                          fps, (DEFAULT_WIDTH, DEFAULT_HEIGHT))while True:    ret, frame = cap.read()    frame = cv2.resize(frame, (DEFAULT_WIDTH, DEFAULT_HEIGHT))    tracking(frame, model)    cv2.imshow("Output", frame)    writer.write(frame)    if cv2.waitKey(1) & 0xFF == ord('q'):        breakcap.release()writer.release()cv2.destroyAllWindows()